<?php declare(strict_types=1);namespace NpmGateway\Services;
final class RmAuditRichTextSanitizer{
 private const TAGS=['p','br','strong','b','em','i','u','ol','ul','li','a'];
 public function sanitize(string$html):array{if(strlen($html)>50000)throw new \InvalidArgumentException('Audit Findings are too long.');$dom=new \DOMDocument('1.0','UTF-8');$old=libxml_use_internal_errors(true);$dom->loadHTML('<?xml encoding="UTF-8"><div id="audit-root">'.$html.'</div>',LIBXML_HTML_NOIMPLIED|LIBXML_HTML_NODEFDTD);libxml_clear_errors();libxml_use_internal_errors($old);$root=$dom->getElementById('audit-root');if(!$root)throw new \InvalidArgumentException('Audit Findings are required.');$this->clean($root);$out='';foreach(iterator_to_array($root->childNodes)as$n)$out.=$dom->saveHTML($n);$out=trim($out);$text=$this->plainText($out);if($text==='')throw new \InvalidArgumentException('Audit Findings are required.');return['html'=>$out,'text'=>$text];}
 public function plainText(string$html):string{$v=(string)preg_replace('/<(?:br\s*\/?>|\/p>|\/li)>/i',"\n",$html);return trim((string)preg_replace('/\n{3,}/',"\n\n",html_entity_decode(strip_tags($v),ENT_QUOTES|ENT_HTML5,'UTF-8')));}
 private function clean(\DOMNode$p):void{foreach(iterator_to_array($p->childNodes)as$n){if(!$n instanceof \DOMElement)continue;$tag=strtolower($n->tagName);if(!in_array($tag,self::TAGS,true)){if(in_array($tag,['script','style','img','video','iframe','object','embed','svg','audio'],true)){$p->removeChild($n);continue;}while($n->firstChild)$p->insertBefore($n->firstChild,$n);$p->removeChild($n);continue;}foreach(iterator_to_array($n->attributes)as$a)if($tag!=='a'||!in_array(strtolower($a->name),['href','title'],true))$n->removeAttribute($a->name);if($tag==='a'){if(!$this->safe($n->getAttribute('href')))$n->removeAttribute('href');else{$n->setAttribute('target','_blank');$n->setAttribute('rel','noopener noreferrer');}}$this->clean($n);}}
 private function safe(string$u):bool{$p=parse_url($u);return$u!==''&&!preg_match('/[\x00-\x20\x7F]/',$u)&&is_array($p)&&!isset($p['user'],$p['pass'])&&in_array(strtolower((string)($p['scheme']??'')),['http','https'],true);}
}
